import json,uuid,copy
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
B='http://localhost:3002';F=json.loads(Path('.tmp-check/task-archive-fixture.json').read_text(encoding='utf-8'));M=json.loads(Path('.tmp-check/task-archive-manager.json').read_text(encoding='utf-8'));A=json.loads(Path('.tmp-check/workspace-accounts.json').read_text(encoding='utf-8'))['accounts'];R=[]
def passed(s):R.append(s);print('PASS '+s,flush=True)
with sync_playwright() as p:
 browser=p.chromium.launch();c=browser.new_context(base_url=B,viewport={'width':1366,'height':900},extra_http_headers={'Origin':B});assert c.request.post('/api/workspace/login',data={'email':M['email'],'password':M['password']}).ok
 rows=c.request.get('/api/workspace/task-archive').json()['records'];assert {F['own'],F['archivedBy']} <= {r['id'] for r in rows};assert F['foreign'] not in {r['id'] for r in rows};assert c.request.get('/api/workspace/task-archive?id='+F['foreign']).status==404;passed('manager scope is creator or archiver, collaborator alone does not grant archive access')
 r=c.request.get('/api/workspace/task-archive?id='+F['own']);assert r.ok,r.text();d=r.json();assert d['total']==2 and d['done']==2 and len(d['logs'])==4 and d['state']['s']=='重新確認完成';passed('archive progress includes substeps and latest uncheck/recheck; full timeline preserved')
 body={'id':F['own'],'version':d['workspace_version'],'writeId':str(uuid.uuid4())};bad=copy.deepcopy(body);bad['id']=F['foreign'];assert c.request.post('/api/workspace/task-archive',data=bad).status==404
 stale=copy.deepcopy(body);stale['version']-=1;assert c.request.post('/api/workspace/task-archive',data=stale).status==409
 r=c.request.post('/api/workspace/task-archive',data=body);assert r.ok,r.text();new=r.json()['id'];assert c.request.post('/api/workspace/task-archive',data=body).json()['id']==new;changed=copy.deepcopy(body);changed['version']+=1;assert c.request.post('/api/workspace/task-archive',data=changed).status==409;passed('copy is scoped, version checked and idempotent')
 r=c.request.get('/api/workspace/task-detail?id='+new);assert r.ok,r.text();newdata=r.json();assert newdata['total']==2 and newdata['done']==0 and not newdata['logs'] and newdata['status']=='pending';assert len(newdata['collaborators'])==1 and newdata['collaborators'][0]['user_id']==M['id'];assert any(r['id']==new for r in c.request.get('/api/workspace/tasks').json()['records']);assert c.request.get('/api/workspace/task-archive?id='+F['own']).json()['logs']==d['logs'];passed('copy appears in My Tasks, starts empty, only current collaborator; original unchanged')
 denied=p.request.new_context(base_url=B,extra_http_headers={'Origin':B});a=next(a for a in A if a['key']=='viewer');assert denied.post('/api/workspace/login',data={'email':a['email'],'password':a['password']}).ok;assert denied.get('/api/workspace/task-archive').status==403;assert denied.post('/api/workspace/task-archive',data=body).status==403;passed('archive capability enforced for list and copy')
 page=c.new_page();page.goto('/workspace/index.html');page.get_by_role('button',name='已封存任務 新版',exact=True).click();page.locator('[data-record-id="'+F['own']+'"]').get_by_role('button',name='查看封存紀錄').click();panel=page.locator('[role=tabpanel]:visible');expect(panel.get_by_role('heading',name=F['title'],exact=True)).to_be_visible();expect(panel.get_by_role('heading',name='執行時間軌跡')).to_be_visible();assert panel.get_by_role('checkbox').count()==0;panel.get_by_role('button',name='複製為新任務').click();dialog=page.get_by_role('dialog',name='複製封存任務');dialog.get_by_role('button',name='取消',exact=True).click();expect(dialog).to_have_count(0);passed('native archive detail is read-only and copy can be cancelled')
 panel.get_by_role('button',name='複製為新任務').click();page.route('**/api/workspace/task-archive',lambda route:route.fulfill(status=503,content_type='application/json',body=json.dumps({'error':'測試暫時失敗'})));dialog.get_by_role('button',name='確認複製',exact=True).click();expect(dialog.get_by_role('alert')).to_contain_text('測試暫時失敗');page.unroute('**/api/workspace/task-archive');dialog.get_by_role('button',name='確認複製',exact=True).click();expect(panel.get_by_role('button',name='開啟新任務')).to_be_visible();panel.get_by_role('button',name='開啟新任務').click();panel=page.locator('[role=tabpanel]:visible');expect(panel.get_by_role('checkbox',name='Vue 封存主項',exact=False)).not_to_be_checked();panel.get_by_role('checkbox',name='Vue 封存主項',exact=False).check();panel.get_by_role('button',name='儲存進度',exact=True).click();expect(panel.get_by_text('任務進度已儲存',exact=True)).to_be_visible();passed('copy failure retry and opening/editing the copied task operate natively')
 page.get_by_role('tab',name='封存 · '+F['title'],exact=True).click();panel=page.locator('[role=tabpanel]:visible');panel.get_by_role('heading',name=F['title'],exact=True).scroll_into_view_if_needed();page.screenshot(path='.tmp-check/task-archive-desktop.png');page.set_viewport_size({'width':390,'height':844});page.screenshot(path='.tmp-check/task-archive-mobile.png');assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');passed('archive desktop/mobile rendering and no page overflow');browser.close()
Path('.tmp-check/task-archive-results.json').write_text(json.dumps(R,ensure_ascii=False,indent=2),encoding='utf-8')
